package onlinejavatraining;

public class Stringparam {

	public static void main(String[] args) {// 'ma' +ctrl space
		// TODO Auto-generated method stub
		System.out.println("HI");// to print anything in java System.out.println() is the only method 'syso'
									// ctrl+space
		System.out.println("Bye");// anything inside the "" double quotes is the string parameter
		amethod();
		bmethod();
	}

	// user defined method
	public static void amethod() {
		System.out.println("hello a method");
	}

	// user defined method
	public static void bmethod() {
		System.out.println("Hello b method");
	}

}
